import os
import shutil

def rotate_logs(log_dir, max_rotations):
    log_files = sorted(os.listdir(log_dir), reverse=True)
    rotated_logs = 0

    for i in range(1, len(log_files)):
        shutil.move(os.path.join(log_dir, log_files[i]), os.path.join(log_dir, log_files[i] + '.' + str(rotated_logs)))
        rotated_logs += 1

        if rotated_logs >= max_rotations:
            break

def archive_logs(log_dir, max_rotations):
    rotate_logs(log_dir, max_rotations)

if __name__ == "__main__":
    log_dir = "/var/log/myapp"
    archive_logs(log_dir, 5)

