import os
import tarfile
from datetime import datetime

def extract_meditation(filename):
    tar = tarfile.open(filename)
    tar.extractall(path="../")

    meditation_file = tar.getmember("meditation.mp3")
    return meditation_file.mtime

def get_new_meditations(meditation_dir):
    new_meditations = []

    for tar_file in os.listdir(meditation_dir):
        if tar_file.endswith(".tar"):
            mtime = extract_meditation(os.path.join(meditation_dir, tar_file))

            if mtime > datetime.now().timestamp():
                new_meditations.append(tar_file)

    return new_meditations

