class Recipe:
    def __init__(self, name):
        self.name = name
        self.steps = []

    def add_step(self, step):
        self.steps.append(step)

    def get_steps(self):
        return self.steps

class MealPlan:
    def __init__(self):
        self.recipes = []

    def add_recipe(self, recipe):
        self.recipes.append(recipe)

    def get_recipes(self):
        return self.recipes

def generate_grocery_list(meal_plan):
    ingredients = []
    for recipe in meal_plan.get_recipes():
        for step in recipe.get_steps():
            for ingredient in step['ingredients']:
                if ingredient not in ingredients:
                    ingredients.append(ingredient)
    return ingredients

def main():
    meal_plan = MealPlan()

    recipe1 = Recipe("Spaghetti Carbonara")
    recipe1.add_step({
        'ingredients': ['ground pork', 'pancetta', 'eggs'],
        'description': 'Cook the pasta according to package instructions.'
    })

    recipe2 = Recipe("Bacon, Lettuce, and Tomato Sandwich")
    recipe2.add_step({
        'ingredients': ['bacon', 'lettuces', 'tomatoes'],
        'description': 'Place the lettuce, bacon, and tomato on the sandwich bread.'
    })

    meal_plan.add_recipe(recipe1)
    meal_plan.add_recipe(recipe2)

    grocery_list = generate_grocery_list(meal_plan)
    print('Grocery List:')
    for item in grocery_list:
        print(item)

if __name__ == '__main__':
