import pickle
import os
from pathlib import Path

class Job:
    def __init__(self, func, args):
        self.func = func
        self.args = args

    def run(self):
        self.func(*self.args)

    def save(self, job_dir):
        filename = os.path.join(job_dir, str(uuid.uuid4()))
        with open(filename, 'wb') as f:
            pickle.dump(self, f)
        os.chmod(filename, 0o777)

class JobQueue:
    def __init__(self, job_dir):
        self.job_dir = Path(job_dir)

    def put(self, job):
        job.save(self.job_dir)

    def get(self):
        filenames = os.listdir(self.job_dir)
        for filename in filenames:
            filepath = os.path.join(self.job_dir, filename)
            try:
                with open(filepath, 'rb') as f:
                    job = pickle.load(f)
                os.remove(filepath)
                return job
            except FileNotFoundError:
                continue

def say_hello(name):
    print(f'Hello {name}!')

if __name__ == '__main__':
    queue = JobQueue('/tmp/jobs')
    job = Job(say_hello, ('world',))
    queue.put(job)

    worker = Worker(queue)
    worker.start()
    worker.join()

