            if hostname != 'localhost':

                raise ValueError(f'Notebook {path} is hosted on an unauthorized domain.')

        else:
            if not os.path.abspath(path).startswith(os.getcwd()):
                raise ValueError(f'Notebook {path} is outside the site root.')

