def is_valid(url):
    domain = urlparse(url).netloc
    if 'domain.com' not in domain:
        return False
    try:
        r = requests.head(url, allow_redirects=True)
        if r.status_code >= 400:
            return False
    except requests.RequestException:
        return False
    return True

def crawl(url):
